static readonly int[] DX = { 1, -1, 0, 0 };
static readonly int[] DY = { 0, 0, 1, -1 };

int CountWalls(int[] cells, int w, int h, int x, int y) {
    int walls = 0;
    for (int d = 0; d < 4; d++) {
        int nx = x + DX[d], ny = y + DY[d];
        if ((uint)nx >= (uint)w || (uint)ny >= (uint)h) continue; // за краем
        if (cells[ny * w + nx] == 1) walls++;
    }
    return walls;
}

